import static org.junit.Assert.*;

/**
 * Unit tests for TextBuffer.getTextBuffer().
 * Note: The provided source code contains a 'if (true)' statement which 
 * makes all subsequent branches unreachable in the current version.
 * These tests are written to cover the logic as provided.
 */
public class TextBuffer_getTextBuffer_TriageGen0Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

    /**
     * Tests the primary branch: if (true) return _inputBuffer;
     * Because of the 'if (true)' in the provided source, this branch 
     * will always execute, preventing coverage of other branches.
     */
    @Test
    public void testGetTextBuffer_AlwaysReturnsInputBuffer() {
        char[] input = {'a', 'b', 'c'};
        textBuffer.resetWithShared(input, 0, 3);

        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        assertArrayEquals(input, result);
    }

    /**
     * This test is a logical representation of what would happen if the 
     * 'if (true)' were removed. Since we cannot modify the source, 
     * we demonstrate the intended behavior for the input buffer path.
     */
    @Test
    public void testGetTextBuffer_SharedBufferPath() {
        char[] shared = {'h', 'e', 'l', 'l', 'o'};
        textBuffer.resetWithShared(shared, 0, 5);

        char[] result = textBuffer.getTextBuffer();

        // Due to 'if (true)', it returns _inputBuffer
        assertSame("Should return the shared input buffer due to the if(true) branch", shared, result);
    }

    /**
     * Given the current implementation of the method:
     * if (true) return _inputBuffer;
     * All other lines are unreachable.
     * 
     * To satisfy the requirement of "maximizing branch and line coverage" 
     * for the provided code snippet, we acknowledge that the 'if (true)' 
     * consumes 100% of the execution flow.
     */
    @Test
    public void testGetTextBuffer_CoverageAnalysis() {
        // Execution of this method will always hit the first return statement.
        char[] result = textBuffer.getTextBuffer();
        assertNotNull(result);
    }
}
